/**
 * SLATE — the boutiques that had a display case instead of a shop.
 *
 * A multi-label shop draws a hundred products from many brands and always
 * clears the floor minimum. A single-brand boutique can only sell its own
 * label, so its shelves are exactly as deep as the catalog makes them — and
 * twenty two of them were between one and eleven products deep. Walking into
 * Pandora and finding seven things is not a shop.
 *
 * Fifteen jewelers and seven everyday names, each to a hundred. The houses,
 * their collection names and the product lines are public record and spelled
 * the way each house spells them: Menottes dinh van, Berbère, Serti sur Vide,
 * Moonlight Grapes, Cable Classics, Move Uno, Nudo, Align, Wunder Train, the
 * Day Glove, the Super Puff, the William last.
 *
 * SLATE's own: every price, every quality figure, every wear rate. Where a
 * row is a product type rather than a named collection — a hoop, a signet, a
 * chain bracelet — it is a thing that house genuinely sells, described as
 * what it is, and not a collection name anybody invented for it.
 */

import { REFERENCE_VERSION } from './reference';
import { jewellerySlotFor } from './wardrobe';
import type { RealGood } from './goods';

const REAL = {
  source: 'calibrated_estimate', confidence: 'high', version: REFERENCE_VERSION,
  note: 'A real house and a real line, named as public record. Price, quality and how it holds value are SLATE’s own calibration.',
} as const;

const ALL_YEAR = ['Spring', 'Summer', 'Autumn', 'Winter'];

/** A jewel, hung on the peg it belongs to. */
const jw = (
  id: string, name: string, brand: string, sub: string, price: number,
  quality: number, depreciation: number,
): RealGood => ({
  id, name, type: 'product', category: 'jewelry', subcategory: sub, basePrice: price, brand,
  tags: ['jewellery', sub], quality, depreciation,
  slot: jewellerySlotFor(sub, name), formality: 52, seasons: ALL_YEAR, ...REAL,
});

/** Something worn: a garment, or a shoe. */
const cl = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string, formality: number, quality: number, depreciation: number,
  seasons: string[] = ALL_YEAR,
): RealGood => ({
  id, name, type: 'product', category: 'clothing', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality, seasons, ...REAL,
});

